%[text] # El Problema de la propina
%[text] Inferencias tipo Mamdani
%[text] 1. Fuzzificar las entradas´mediante las funciones de pertenencia
%[text] 2. Evaluar en las reglas
%[text] 3. Desfuzzificar las salidas \
%[text] Reglas:
%[text] 1. "Si el servicio es excelente y la comida es muy buena entonces la propina es alta"
%[text] 2. "Si el servicio es aceptable, la propina es media"
%[text] 3. "Si el servicio es pobre y la comida es mala la propina es baja" \
%[text] ## Funciones de pertenencia
clear; clc;close all;

%Universos de discurso
lim_e = 0:0.001:10;     % entradas (comida y servicio)
lim_p = 0:0.001:25;     % salida (propina)

%COMIDA
Pertenencia.comida.mala = [0 0 2 4];
Pertenencia.comida.regular = [2 4 6 8];    
Pertenencia.comida.muybuena = [7 9 10 10];

%SERVICIO
Pertenencia.servicio.pobre = [0 0 2 5];
Pertenencia.servicio.aceptable = [4 5 6 7];
Pertenencia.servicio.excelente = [7 8 10 10];

%PROPINA
Pertenencia.propina.baja  = [0 0 5 10];
Pertenencia.propina.media = [5 10 15 20];
Pertenencia.propina.alta  = [15 20 25 25];

%COMIDA
u_mala = trapmf(lim_e,Pertenencia.comida.mala);
u_regular = trapmf(lim_e,Pertenencia.comida.regular);
u_muybueno = trapmf(lim_e,Pertenencia.comida.muybuena);

%SERVICIO
u_pobre = trapmf(lim_e,Pertenencia.servicio.pobre);
u_aceptable = trapmf(lim_e,Pertenencia.servicio.aceptable);
u_excelente = trapmf(lim_e,Pertenencia.servicio.excelente);

%PROPINA
u_baja = trapmf(lim_p,Pertenencia.propina.baja);
u_media = trapmf(lim_p,Pertenencia.propina.media);
u_alta = trapmf(lim_p,Pertenencia.propina.alta);

figure; %[output:49f4500c]
subplot(3,1,1) %[output:49f4500c]
plot(lim_e,u_mala,'LineWidth',2); %[output:49f4500c]
hold on; %[output:49f4500c]
plot(lim_e,u_regular,'LineWidth',2); %[output:49f4500c]
hold on; %[output:49f4500c]
plot(lim_e,u_muybueno,'LineWidth',2); %[output:49f4500c]
grid on; %[output:49f4500c]
xlabel('Comida'); %[output:49f4500c]
ylabel('Grado de pertenencia'); %[output:49f4500c]
legend('Mala','Regular','Muy buena'); %[output:49f4500c]
title('Funciones de pertenencia - Comida'); %[output:49f4500c]

subplot(3,1,2) %[output:49f4500c]
plot(lim_e,u_pobre,'LineWidth',2); %[output:49f4500c]
hold on; %[output:49f4500c]
plot(lim_e,u_aceptable,'LineWidth',2); %[output:49f4500c]
hold on; %[output:49f4500c]
plot(lim_e,u_excelente,'LineWidth',2); %[output:49f4500c]
grid on; %[output:49f4500c]
xlabel('Servicio'); %[output:49f4500c]
ylabel('Grado de pertenencia'); %[output:49f4500c]
legend('Pobre','Aceptable','Excelente'); %[output:49f4500c]
title('Funciones de pertenencia - Servicio'); %[output:49f4500c]

subplot(3,1,3) %[output:49f4500c]
plot(lim_p,u_baja,'LineWidth',2); %[output:49f4500c]
hold on; %[output:49f4500c]
plot(lim_p,u_media,'LineWidth',2); %[output:49f4500c]
hold on; %[output:49f4500c]
plot(lim_p,u_alta,'LineWidth',2); %[output:49f4500c]
grid on; %[output:49f4500c]
xlabel('Propina'); %[output:49f4500c]
ylabel('Grado de pertenencia'); %[output:49f4500c]
legend('Baja','Media','Alta'); %[output:49f4500c]
title('Funciones de pertenencia - Propina'); %[output:49f4500c]

drawnow
%[text] ## Ingreso de valores
fprintf('\n Problema de la propina \n'); %[output:53838109]
servicio = pedirValor('Calificación del SERVICIO (0 a 10): '); %[output:2ee0a5bf]
comida = pedirValor('Calificación de la COMIDA (0 a 10): ');
U_out   = [u_alta ; u_media ; u_baja];

%[text] ## Resultados
propina_defecto = 12.5; %Valor por efecto
[pIn, wIn, muOutIn, salidasIn] = inferencia(servicio, comida, Pertenencia, lim_p, U_out, propina_defecto);

%Resultado inferencia
fprintf('Servicio = %g,  Comida = %g\n', servicio, comida); %[output:1f391936]
fprintf('Activación de reglas:\n'); %[output:17cf3ef9]
fprintf('R1 (Excelente Y Muy buena -> Alta)  w1 = %.3f\n', wIn(1)); %[output:276b0de5]
fprintf('R2 (Aceptable -> Media)             w2 = %.3f\n', wIn(2)); %[output:0e1ab368]
fprintf('R3 (Pobre Y Mala -> Baja)           w3 = %.3f\n', wIn(3)); %[output:2b2fa5f0]
if all(wIn == 0)
    fprintf('Ninguna regla se activa: se usa el valor por defecto.\n');
end
fprintf('PROPINA SUGERIDA = %.2f %\n', pIn); %[output:4d4028e6]

%Grafica inferencia
figure; hold on; grid on; %[output:8d88805e]
plot(lim_p, u_baja, ':', lim_p, u_media, ':', lim_p, u_alta, ':', 'Color', [0.5 0.5 0.5]); %[output:8d88805e]
plot(lim_p, salidasIn(1,:), 'g--', lim_p, salidasIn(2,:), 'm--', lim_p, salidasIn(3,:), 'c--'); %[output:8d88805e]
area(lim_p, muOutIn, 'FaceColor', [0.3 0.6 0.9], 'FaceAlpha', 0.4, 'EdgeColor', 'b'); %[output:8d88805e]
xline(pIn, 'r', 'LineWidth', 2); %[output:8d88805e]
xlabel('Propina (%)'); ylabel('\mu'); ylim([0 1.1]); %[output:8d88805e]
title(sprintf('w = [%.2f %.2f %.2f]  ->  Propina = %.2f %', wIn, pIn)); %[output:8d88805e]
legend('Baja','Media','Alta','R1 truncada','R2 truncada','R3 truncada','Agregada','Centroide'); %[output:8d88805e]

% Superficie de control
[S, C] = meshgrid(0:0.25:10, 0:0.25:10); %Ejes x y y
P = zeros(size(S));
for i = 1:numel(S) 
    P(i) = inferencia(S(i), C(i), Pertenencia, lim_p, U_out, propina_defecto);
end

figure; %[output:2c12fbb1]
surf(S, C, P, 'FaceAlpha', 0.8); %[output:2c12fbb1]
hold on; %[output:2c12fbb1]
plot3(servicio, comida, pIn, 'ro', 'MarkerSize', 12, 'MarkerFaceColor', 'r');   % punto ingresado %[output:2c12fbb1]
plot3([servicio servicio], [comida comida], [min(P(:)) pIn], 'r--', 'LineWidth', 1.5); %[output:2c12fbb1]
text(servicio, comida, pIn + 1.5, sprintf('  %.2f %', pIn), 'Color', 'r', 'FontWeight', 'bold'); %[output:2c12fbb1]
xlabel('Servicio'); ylabel('Comida'); zlabel('Propina (%)'); %[output:2c12fbb1]
title('Superficie de control difusa'); %[output:2c12fbb1]
colorbar; view(-37.5, 30); %[output:2c12fbb1]
hold off; %[output:2c12fbb1]
drawnow

%[text] ## Funciones
function t = tnorm(a,b) %Función T-norm "Y"
    t = min(a,b);
end

function s = snorm(a,b) %Función S-norm "O"
    s = max(a,b);
end

function gp = trapecio(x, p) %Calcular el grado de pertenencia en los trapecios
    a = p(1); b = p(2); c = p(3); d = p(4);
    gp = zeros(size(x));
    if b > a                     % tramo de subida
        idx = (x > a) & (x < b);
        gp(idx) = (x(idx) - a) / (b - a);
    end
        gp((x >= b) & (x <= c)) = 1; % centro
    if d > c                      % tramo de bajada
        idx = (x > c) & (x < d);
        gp(idx) = (d - x(idx)) / (d - c);
    end
end

function [propina, w, muOut, salidas] = inferencia(servicio, comida, Pertenencia, lim_p,U_out, propinaDefecto)

%FUZZIFICACIÓN
sPobre     = trapecio(servicio, Pertenencia.servicio.pobre);
sAceptable = trapecio(servicio, Pertenencia.servicio.aceptable);
sExcelente = trapecio(servicio, Pertenencia.servicio.excelente);
cMala      = trapecio(comida, Pertenencia.comida.mala);
cRegular   = trapecio(comida, Pertenencia.comida.regular);
cMuyBuena  = trapecio(comida, Pertenencia.comida.muybuena);

%REGLAS
w1 = tnorm(sExcelente, cMuyBuena);   %Alta
w2 = sAceptable;                     %Media
w3 = tnorm(sPobre, cMala); %Baja
w  = [w1 w2 w3];

%T-norm
salidas = [tnorm(w1, U_out(1,:)) ;
    tnorm(w2, U_out(2,:)) ;
    tnorm(w3, U_out(3,:)) ];

%S-Norm
muOut = snorm(snorm(salidas(1,:), salidas(2,:)), salidas(3,:));

% Etapa 3: DEFUZZIFICACIÓN (centroide) ---
areaTotal = trapz(lim_p, muOut);
if areaTotal == 0
    propina = propinaDefecto;
else
    propina = trapz(lim_p, lim_p .* muOut) / areaTotal;
end
end

function v = pedirValor(entrada) %Pide un número entre 0 y 10
while true
    v = input(entrada);
    if isnumeric(v) && isscalar(v) && isreal(v) && v >= 0 && v <= 10
        return;
    end
    fprintf('Valor inválido: debe ser número entre 0 y 10.\n');
end
end






